                            "values": [{"id": mapping_id, "src": "hda"}]
                        },
                        "mapping_source|mapping_has_header": "true",
                        "mapping_source|mapping_gene_column": "1",
                        "mapping_source|mapping_pathway_column": "2",
                        "mapping_source|mapping_name_column": "3",
                        "p_adjust_scope": "all_pathways"
                    }
                }

                r2 = requests.post(f"{base_url}/tools", headers={**headers, "Content-Type": "application/json"}, json=payload)
